CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('student','teacher','admin') DEFAULT 'student');
CREATE TABLE IF NOT EXISTS problems (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) UNIQUE NOT NULL, title VARCHAR(255) NOT NULL, topic VARCHAR(100) DEFAULT '', difficulty VARCHAR(20) DEFAULT 'easy', created_by INT, current_version_id INT);
CREATE TABLE IF NOT EXISTS problem_versions (id INT AUTO_INCREMENT PRIMARY KEY, problem_id INT NOT NULL, version_no INT DEFAULT 1, statement MEDIUMTEXT, input_spec TEXT, output_spec TEXT, public_examples JSON, time_limit_ms INT DEFAULT 2000, memory_limit_kb INT DEFAULT 262144, testset_version VARCHAR(32) DEFAULT 'v1', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS test_cases (id INT AUTO_INCREMENT PRIMARY KEY, problem_version_id INT NOT NULL, testset_version VARCHAR(32) NOT NULL, ordinal INT NOT NULL, input_data MEDIUMTEXT, expected_output MEDIUMTEXT, is_public TINYINT DEFAULT 0, weight INT DEFAULT 1, INDEX (problem_version_id, testset_version));
CREATE TABLE IF NOT EXISTS submissions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, problem_version_id INT NOT NULL, language ENUM('python','cpp') NOT NULL, source_code MEDIUMTEXT NOT NULL, idempotency_key VARCHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, idempotency_key));
CREATE TABLE IF NOT EXISTS judging_runs (id INT AUTO_INCREMENT PRIMARY KEY, submission_id INT NOT NULL, testset_version VARCHAR(32) NOT NULL, status ENUM('QUEUED','RUNNING','DONE','SYSTEM_ERROR','RETRY_PENDING') DEFAULT 'QUEUED', verdict VARCHAR(32), score INT DEFAULT 0, attempt INT DEFAULT 0, lease_token VARCHAR(64), lease_expires_at DATETIME, is_current TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, started_at DATETIME, finished_at DATETIME);
CREATE TABLE IF NOT EXISTS case_results (id INT AUTO_INCREMENT PRIMARY KEY, judging_run_id INT NOT NULL, test_case_id INT NOT NULL, verdict VARCHAR(32), time_ms INT DEFAULT 0, memory_kb INT DEFAULT 0, stderr_excerpt VARCHAR(2000));
CREATE TABLE IF NOT EXISTS classes (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS class_members (class_id INT NOT NULL, user_id INT NOT NULL, role VARCHAR(20) DEFAULT 'student', PRIMARY KEY (class_id, user_id));
CREATE TABLE IF NOT EXISTS drafts (user_id INT NOT NULL, problem_id INT NOT NULL, language VARCHAR(10) DEFAULT 'python', code MEDIUMTEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (user_id, problem_id));
